/**
 * Measures the per-tuple decoding overhead of {@link ChunkInput} in isolation from LMDB.
 * <p>
 * Setup encodes {@link #TOTAL_TUPLES} sorted quads into chunks of {@code chunkSize} tuples with {@link ChunkOutput},
 * placing every chunk's key and value sections in direct, native-order buffers (the shape LMDB hands to the record
 * iterators). The benchmarks report the average time per decoded tuple and compare:
 * </p>
 * <ul>
 * <li>{@code baselineArray}: reading the same tuples from a {@code long[][]} (memory floor);</li>
 * <li>{@code baselineVarintQuad}: the legacy one-record-per-tuple layout, four varints per tuple;</li>
 * <li>{@code iterateReused}: one cached {@link ChunkInput} reset per chunk, as in {@code LmdbRecordIterator};</li>
 * <li>{@code iterateFresh}: a new non-cached {@link ChunkInput} per chunk, as in the store scan helpers;</li>
 * <li>{@code iterateRewindReused}: decode, {@link ChunkInput#rewind()} and replay the cached tuples;</li>
 * <li>{@code seekLastReused}: {@link ChunkInput#seek(long[])} to the last tuple of every chunk.</li>
 * </ul>
 * <p>
 * {@code distribution=dense} produces small deltas in the last column and constant earlier suffix columns (bit-packed
 * and constant sections); {@code sparse} produces random suffix values with large gaps (wide packed/varint sections).
 * </p>
 */
@State(Scope.Benchmark)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@BenchmarkMode(Mode.AverageTime)
@Fork(value = 1, jvmArgs = { "-Xms1G", "-Xmx1G" })
@OutputTimeUnit(TimeUnit.NANOSECONDS)
public class ChunkInputBenchmark {

	static final int TOTAL_TUPLES = 1 << 15;
	private static final int ELEMENTS = 4;

	@Param({ "32" })
	public int chunkSize;

	@Param({ "1" })
	public int splitPoint;

	@Param({ "dense", "sparse" })
	public String distribution;

	private long[][] tuples;
	private ByteBuffer[] keys;
	private ByteBuffer[] values;
	private long[][] lastTuples;
	private ByteBuffer legacy;
	private final ChunkInput reused = new ChunkInput();

	@Setup
	public void setup() {
		if (chunkSize < 1 || chunkSize > Chunks.MAX_CHUNK_SIZE || TOTAL_TUPLES % chunkSize != 0) {
			throw new IllegalArgumentException("Unsupported chunkSize " + chunkSize);
		}
		SplittableRandom random = new SplittableRandom(42);
		int chunkCount = TOTAL_TUPLES / chunkSize;
		tuples = new long[TOTAL_TUPLES][];
		keys = new ByteBuffer[chunkCount];
		values = new ByteBuffer[chunkCount];
		lastTuples = new long[chunkCount][];

		ChunkOutput output = new ChunkOutput(Chunks.MAX_CHUNK_SIZE, ELEMENTS, splitPoint);
		ByteBuffer keyScratch = ByteBuffer.allocate(64).order(ByteOrder.nativeOrder());
		ByteBuffer valueScratch = ByteBuffer.allocate(4096).order(ByteOrder.nativeOrder());
		ByteBuffer legacyScratch = ByteBuffer.allocateDirect(TOTAL_TUPLES * ELEMENTS * 9)
				.order(ByteOrder.nativeOrder());

		for (int c = 0; c < chunkCount; c++) {
			long[][] chunk = generateChunk(random);
			output.reset(ELEMENTS, splitPoint);
			for (long[] tuple : chunk) {
				if (!output.addTuple(tuple)) {
					throw new IllegalStateException("Chunk overflow");
				}
				for (long v : tuple) {
					Varint.writeUnsigned(legacyScratch, v);
				}
			}
			keyScratch.clear();
			valueScratch.clear();
			output.write(keyScratch, valueScratch);
			keys[c] = toDirect(keyScratch.flip());
			values[c] = toDirect(valueScratch.flip());
			System.arraycopy(chunk, 0, tuples, c * chunkSize, chunkSize);
			lastTuples[c] = chunk[chunkSize - 1];
		}
		legacy = legacyScratch.flip().slice().order(ByteOrder.nativeOrder());
		verify();
	}

	private long[][] generateChunk(SplittableRandom random) {
		long[] prefix = new long[splitPoint];
		for (int i = 0; i < splitPoint; i++) {
			prefix[i] = 1 + random.nextLong(1_000_000L);
		}
		int suffix = ELEMENTS - splitPoint;
		long[][] chunk = new long[chunkSize][];
		if ("dense".equals(distribution)) {
			long[] base = new long[suffix];
			for (int e = 0; e < suffix; e++) {
				base[e] = 1 + random.nextLong(1_000_000L);
			}
			long last = base[suffix - 1];
			for (int t = 0; t < chunkSize; t++) {
				long[] tuple = new long[ELEMENTS];
				System.arraycopy(prefix, 0, tuple, 0, splitPoint);
				System.arraycopy(base, 0, tuple, splitPoint, suffix);
				tuple[ELEMENTS - 1] = last;
				last += 1 + random.nextInt(3);
				chunk[t] = tuple;
			}
		} else if ("sparse".equals(distribution)) {
			for (int t = 0; t < chunkSize; t++) {
				long[] tuple = new long[ELEMENTS];
				System.arraycopy(prefix, 0, tuple, 0, splitPoint);
				for (int e = splitPoint; e < ELEMENTS; e++) {
					tuple[e] = 1 + random.nextLong(1L << 30);
				}
				// a distinct tie breaker in the last column keeps the tuples unique after sorting
				tuple[ELEMENTS - 1] = (tuple[ELEMENTS - 1] & ~0x3FL) | t;
				chunk[t] = tuple;
			}
			Arrays.sort(chunk, Chunks::compareTuples);
		} else {
			throw new IllegalArgumentException("Unknown distribution " + distribution);
		}
		return chunk;
	}

	private static ByteBuffer toDirect(ByteBuffer heap) {
		ByteBuffer direct = ByteBuffer.allocateDirect(heap.remaining()).order(ByteOrder.nativeOrder());
		direct.put(heap).flip();
		return direct;
	}

	private void verify() {
		int t = 0;
		for (int c = 0; c < keys.length; c++) {
			keys[c].rewind();
			values[c].rewind();
			reused.reset(keys[c], values[c], ELEMENTS, splitPoint);
			long[] tuple;
			int n = 0;
			while ((tuple = reused.next()) != null) {
				if (!Arrays.equals(tuple, 0, ELEMENTS, tuples[t], 0, ELEMENTS)) {
					throw new IllegalStateException("Decoded tuple mismatch in chunk " + c + ": "
							+ Arrays.toString(tuple) + " != " + Arrays.toString(tuples[t]));
				}
				t++;
				n++;
			}
			if (n != chunkSize) {
				throw new IllegalStateException("Chunk " + c + " decoded " + n + " tuples, expected " + chunkSize);
			}
		}
		if (baselineArray() != iterateReused() || iterateReused() != iterateFresh()
				|| iterateFresh() != baselineVarintQuad() || 2 * iterateReused() != iterateRewindReused()) {
			throw new IllegalStateException("Benchmark checksums disagree");
		}
	}

	private static long sum(long[] tuple) {
		return tuple[0] + tuple[1] + tuple[2] + tuple[3];
	}

	@Benchmark
	@OperationsPerInvocation(TOTAL_TUPLES)
	public long baselineArray() {
		long acc = 0;
		for (long[] tuple : tuples) {
			acc += sum(tuple);
		}
		return acc;
	}

	@Benchmark
	@OperationsPerInvocation(TOTAL_TUPLES)
	public long baselineVarintQuad() {
		ByteBuffer buf = legacy;
		buf.rewind();
		long[] tuple = new long[ELEMENTS];
		long acc = 0;
		for (int i = 0; i < TOTAL_TUPLES; i++) {
			Varint.readQuadUnsigned(buf, tuple);
			acc += sum(tuple);
		}
		return acc;
	}

	@Benchmark
	@OperationsPerInvocation(TOTAL_TUPLES)
	public long iterateReused() {
		ChunkInput input = reused;
		long acc = 0;
		for (int c = 0; c < keys.length; c++) {
			input.reset(keys[c].rewind(), values[c].rewind(), ELEMENTS, splitPoint);
			long[] tuple;
			while ((tuple = input.next()) != null) {
				acc += sum(tuple);
			}
		}
		return acc;
	}

	@Benchmark
	@OperationsPerInvocation(TOTAL_TUPLES)
	public long iterateFresh() {
		long acc = 0;
		for (int c = 0; c < keys.length; c++) {
			ChunkInput input = new ChunkInput(keys[c].rewind(), values[c].rewind(), ELEMENTS, splitPoint);
			long[] tuple;
			while ((tuple = input.next()) != null) {
				acc += sum(tuple);
			}
		}
		return acc;
	}

	@Benchmark
	@OperationsPerInvocation(2 * TOTAL_TUPLES)
	public long iterateRewindReused() {
		ChunkInput input = reused;
		long acc = 0;
		for (int c = 0; c < keys.length; c++) {
			input.reset(keys[c].rewind(), values[c].rewind(), ELEMENTS, splitPoint);
			long[] tuple;
			while ((tuple = input.next()) != null) {
				acc += sum(tuple);
			}
			input.rewind();
			while ((tuple = input.next()) != null) {
				acc += sum(tuple);
			}
		}
		return acc;
	}

	@Benchmark
	@OperationsPerInvocation(TOTAL_TUPLES)
	public long seekLastReused() {
		ChunkInput input = reused;
		long acc = 0;
		for (int c = 0; c < keys.length; c++) {
			input.reset(keys[c].rewind(), values[c].rewind(), ELEMENTS, splitPoint);
			acc += input.seek(lastTuples[c]);
			acc += sum(input.current());
		}
		return acc;
	}

	public static void main(String[] args) throws RunnerException {
		Options opt = new OptionsBuilder()
				.include(ChunkInputBenchmark.class.getSimpleName())
				.build();
		new Runner(opt).run();
	}
}
